const PAYMENT_TERMS_DAYS = 15;
const now = Date.now();
const overdue = items.filter(i => {
  const status = (i.json.status || '').toString().toLowerCase();
  if (status === 'paid') return false;
  const invoiceDate = new Date(i.json.invoice_date).getTime();
  if (isNaN(invoiceDate)) return false;
  const daysSince = (now - invoiceDate) / (24 * 60 * 60 * 1000);
  i.json.days_overdue = Math.round(daysSince - PAYMENT_TERMS_DAYS);
  return daysSince > PAYMENT_TERMS_DAYS;
});
return overdue.map(i => ({ json: {
  client: i.json.client,
  amount: i.json.amount,
  invoice_date: i.json.invoice_date,
  days_overdue: i.json.days_overdue
} }));

const OVERAGE_THRESHOLD_PCT = 20;
const flagged = items.filter(i => {
  const billed = Number(i.json.hours_billed);
  const actual = Number(i.json.hours_actual);
  if (!billed || isNaN(actual)) return false;
  const overagePct = ((actual - billed) / billed) * 100;
  i.json.overage_pct = Math.round(overagePct * 10) / 10;
  return overagePct > OVERAGE_THRESHOLD_PCT;
});
return flagged.map(i => ({ json: {
  client: i.json.client,
  hours_billed: i.json.hours_billed,
  hours_actual: i.json.hours_actual,
  overage_pct: i.json.overage_pct
} }));
